function normaliseText(value) {
return String(value || '')
.replace(/\s+/g, ' ')
.trim();
}
function sameOriginUrl(value) {
try {
const url = new URL(value, location.href);
return url.origin === location.origin ? url : null;
} catch {
return null;
}
}
function missionIdFromUrl(value) {
const url = sameOriginUrl(value);
if (!url) return '';
const match = url.pathname.match(/^\/missions\/(\d+)(?:\/|$)/i);
return match ? match[1] : '';
}
function vehicleIdFromUrl(value) {
const url = sameOriginUrl(value);
if (!url) return '';
const match = url.pathname.match(/^\/vehicles\/(\d+)(?:\/|$)/i);
return match ? match[1] : '';
}
function isMissionUrl(value) {
return Boolean(missionIdFromUrl(value));
}
function missionAlarmSubmissionId(value) {
const url = sameOriginUrl(value);
if (!url) return '';
const match = url.pathname.match(/^\/missions\/(\d+)\/alarm\/?$/i);
return match ? match[1] : '';
}
function canonicalMissionPageId(value) {
const url = sameOriginUrl(value);
if (!url) return '';
const match = url.pathname.match(/^\/missions\/(\d+)\/?$/i);
return match ? match[1] : '';
}
function pathFromUrl(value) {
try {
const url = sameOriginUrl(value);
return url ? `${url.pathname}${url.search || ''}` : '';
} catch {
return '';
}
}
