        missionUpdateBtn.style.backgroundColor = '#0d6efd';
        missionUpdateBtn.style.color = 'white';
        missionUpdateBtn.addEventListener(
            'click',
            async function() {
                if (
                    missionUpdateBtn.disabled
                ) {
                    return;
                }
                missionUpdateBtn.disabled =
                    true;
                beginMissionFinderMemorySensitiveOperation(
                    'manual Mission Update'
                );
                const originalText =
                    missionUpdateBtn.textContent;
                missionUpdateBtn.textContent =
                    'Loading...';
                try {
                    updateStatusBox(
                        'Mission Update: loading the full available vehicle list...'
                    );
                    const manualVehicleLoadState =
                        await ensureVehicleListLoaded({
                            requireNonZero: true
                        });
                    if (!manualVehicleLoadState.ready) {
                        vehicleLoadState.ready = false;
                        changeDispatchBoxColor(false);
                        updateStatusBox(
                            'Mission Update stopped: the complete vehicle list did not become stable.'
                        );
                        return;
                    }
                    vehicleLoadState.trainedPersonnelBlocked = false;
                    vehicleLoadState.trainedPersonnelBlockText = '';
                    clearSelectionGuards();
                    // Reconcile this explicit manual operation with the current
                    // page. Historical selections are not dispatched vehicles.
                    mfPatientSelectionLedgerCache = {
                        missionKey: getPatientSelectionMissionKey(), counts: {}
                    };
                    savePatientSelectionLedger(mfPatientSelectionLedgerCache);
                    const manualUpdateRows =
                        readMissionUpdateRows();
                    await preparePoliceVehicleSafetyForRows(
                        manualUpdateRows,
                        'MANUAL UPDATE'
                    );
                    handleMissionUpdateUnits(
                        true,
                        manualUpdateRows
                    );
                } finally {
                    endMissionFinderMemorySensitiveOperation(
                        'manual Mission Update'
                    );
                    missionUpdateBtn.disabled =
                        false;
                    missionUpdateBtn.textContent =
                        originalText;
                }
            }
        );
