  const path = v => { const s=String(v??'').replace(/^https:\/\/(?:www|police)\.missionchief\.co\.uk(?=\/)/,''); return /^\/(?!\/)/.test(s) ? s.split(/[?#]/)[0].slice(0,240) : ''; };
