                '.mf-iphone-native-picker-grid, ' +
                '.mf-iphone-native-picker-item, ' +
                '.mf-iphone-native-picker-structural, ' +
                '.mf-iphone-native-picker-search, ' +
                '.mf-iphone-native-picker-strip, ' +
                '.mf-iphone-native-picker-collapsed'
