                        missionKey:
                            missionKeyAtFetchStart,
                        url: sourceDescriptor.url,
                        missionId:
                            sourceDescriptor.missionId,
                        missionTypeId:
                            sourceDescriptor.missionTypeId,
                        tableFound: true,
