    function allyStealSuccessAlertMatchesVehicle(
        alert,
        identity
    ) {
        if (!alert) return false;
        const text = (
            alert.textContent ||
            alert.innerText ||
            ''
        ).replace(/\s+/g, ' ').trim();
        if (
            !/has successfully been dispatched\.?$/i.test(
                text
            )
        ) {
            return false;
        }
        const vehicleLink =
            alert.querySelector(
                'a[href^="/vehicles/"]'
            );
        if (!vehicleLink) return false;
        const alertHref = (
            vehicleLink.getAttribute('href') ||
            ''
        ).split('?')[0].trim();
        const alertName = normaliseVehicleText(
            vehicleLink.textContent ||
            vehicleLink.innerText ||
            ''
        );
        const expectedName =
            normaliseVehicleText(
                identity?.name || ''
            );
        if (
            identity?.href &&
            alertHref === identity.href
        ) {
            return true;
        }
        if (
            identity?.vehicleId &&
            alertHref.includes(
                `/vehicles/${identity.vehicleId}`
            )
        ) {
            return true;
        }
        return (
            !!expectedName &&
            alertName === expectedName
        );
    }
    async function waitForAllyStealDispatchSuccess(
        identity,
        existingAlertIds,
        timeoutMs = 8000
    ) {
        const startedAt = Date.now();
        let lastAlertSignature = '';
        while (Date.now() - startedAt < timeoutMs) {
            const allAlerts =
                getAllAllyStealSuccessAlerts();
            const alertDiagnostics =
                allAlerts.map(alert => ({
                    element:
                        describeAllyDebugElement(
                            alert
                        ),
                    existedBefore:
                        !!alert.id &&
                        existingAlertIds.has(
                            alert.id
                        ),
                    visible:
                        isAllyStealElementVisible(
                            alert
                        ),
                    matchesVehicle:
                        allyStealSuccessAlertMatchesVehicle(
                            alert,
                            identity
                        )
                }));
            const signature =
                safeAllyDebugObject(
                    alertDiagnostics
                );
            if (
                signature !== lastAlertSignature
            ) {
                lastAlertSignature = signature;
                allyStealDebugLog(
                    'SUCCESS ALERT SCAN',
                    alertDiagnostics
                );
            }
            const matchingAlerts =
                allAlerts.filter(alert => {
                    if (
                        alert.id &&
                        existingAlertIds.has(
                            alert.id
                        )
                    ) {
                        return false;
                    }
                    return (
                        isAllyStealElementVisible(
                            alert
                        ) &&
                        allyStealSuccessAlertMatchesVehicle(
                            alert,
                            identity
                        )
                    );
                });
            if (matchingAlerts.length > 0) {
                return matchingAlerts[
                    matchingAlerts.length - 1
                ];
            }
            await wait(150);
        }
        allyStealDebugLog(
            'SUCCESS ALERT WAIT TIMEOUT',
            {
                timeoutMs,
                identity
            }
        );
        return null;
    }
    async function closeAllyStealMissionFromSuccessAlert(
        successAlert
    ) {
        const alertModal =
            successAlert?.closest(
                '.vm--modal, .modal, .lightbox'
            ) ||
            null;
        allyStealDebugLog(
            'CLOSE START',
            {
                successAlert:
                    describeAllyDebugElement(
                        successAlert
                    ),
                alertModal:
                    describeAllyDebugElement(
                        alertModal
                    )
            }
        );
        for (let attempt = 1; attempt <= 8; attempt++) {
            const missionInfo =
                getActiveMissionInfoForAllySteal();
            const activeModal =
                alertModal &&
                alertModal.isConnected &&
                isVisibleForQueueRestart(alertModal)
                    ? alertModal
                    : (
                        missionInfo?.closest(
                            '.vm--modal, .modal, .lightbox'
                        ) ||
                        null
                    );
            allyStealDebugLog(
                `CLOSE ATTEMPT ${attempt} MODAL`,
                describeAllyDebugElement(
                    activeModal
                )
            );
            if (!activeModal) {
                allyStealDebugLog(
                    `CLOSE ATTEMPT ${attempt}`,
                    'No active modal remained; treating mission as already closed.'
                );
                return true;
            }
            const closeButton =
                activeModal.querySelector(
                    '.control-btn-container span.lightbox-close[title="Close"]'
                ) ||
                activeModal.querySelector(
                    'span.lightbox-close[title="Close"]'
                );
            allyStealDebugLog(
                `CLOSE ATTEMPT ${attempt} BUTTON`,
                describeAllyDebugElement(
                    closeButton
                )
            );
            if (!closeButton) {
                allyStealDebugLog(
                    `CLOSE ATTEMPT ${attempt}`,
                    'Close button not found in selected modal.'
                );
                await wait(250);
                continue;
            }
            try {
                closeButton.scrollIntoView({
                    block: 'center',
                    inline: 'center'
                });
            } catch (error) {}
            try {
                closeButton.click();
                allyStealDebugLog(
                    `CLOSE ATTEMPT ${attempt} CLICK`,
                    'Native closeButton.click() called.'
                );
            } catch (error) {
                allyStealDebugLog(
                    `CLOSE ATTEMPT ${attempt} NATIVE ERROR`,
                    {
                        name:
                            error?.name || '',
                        message:
                            error?.message ||
                            String(error)
                    }
                );
                const fallbackResult =
                    realClickForQueueRestart(
                        closeButton
                    );
                allyStealDebugLog(
                    `CLOSE ATTEMPT ${attempt} FALLBACK`,
                    {
                        fallbackResult
                    }
                );
            }
            await wait(500);
            allyStealDebugLog(
                `CLOSE ATTEMPT ${attempt} AFTER WAIT`,
                {
                    modalConnected:
                        activeModal.isConnected,
                    modalVisible:
                        isVisibleForQueueRestart(
                            activeModal
                        ),
                    activeMission:
                        describeAllyDebugElement(
                            getActiveMissionInfoForAllySteal()
                        )
                }
            );
            if (
                !activeModal.isConnected ||
                !isVisibleForQueueRestart(
                    activeModal
                )
            ) {
                return true;
            }
        }
        allyStealDebugLog(
            'CLOSE FAILED',
            'All 8 close attempts finished with the mission modal still visible.'
        );
        return false;
    }
    // Capture at the action boundary: worker document listeners may be absent
    // during lifecycle transitions. This never waits for storage or networking.
    function getNexusDispatchCaptureHealth(owner) {
        const previous = owner.__NEXUS_DISPATCH_CAPTURE__;
        if (previous && Object.getPrototypeOf(previous) === null) return previous;
        // A worker-realm object stored on top pins that worker through its
        // Object.prototype -> constructor -> native context, even without callbacks.
        // Keep only scalar diagnostics in a prototype-free owner-realm record.
        const health = owner.Object.create(null);
        for (const key of ['attempted', 'accepted', 'lastAt']) {
            const value = previous?.[key];
            health[key] = typeof value === 'number' && Number.isFinite(value) ? value : 0;
        }
        for (const key of ['lastError', 'lastMissionId']) {
            health[key] = typeof previous?.[key] === 'string' ? previous[key] : '';
        }
        owner.__NEXUS_DISPATCH_CAPTURE__ = health;
        return health;
    }
    function captureNexusDispatchAction(control) {
        try {
            mfCommitSelectedAmbulancesToMissionLedger(
                'nexus-dispatch-action'
            );
        } catch (_error) {}
        try {
            const owner = window.top;
            const health = getNexusDispatchCaptureHealth(owner);
            health.attempted++;
            const logger = owner.__NEXUS_FULL_LOGGER__;
            if (!logger?.enabled()) { health.lastError = 'Map logger unavailable or recording paused'; return; }
            if (!control || control.disabled || control.hasAttribute('disabled') || control.getAttribute('aria-disabled') === 'true' || control.classList.contains('disabled')) return;
            const missionId = String(location.pathname).match(/\/missions\/(\d+)/)?.[1];
            if (!missionId) return;
            const units = getVehicleCheckboxSnapshot(true).filter(cb => cb.checked).slice(0,500)
                .map(cb => {
                    const vehicleId = getMissionVehicleId(cb);
                    try { return window.__NEXUS_COLLECTOR_GAME__?.unit(cb,vehicleId) || {vehicleId}; }
                    catch { return {vehicleId}; }
                }).filter(unit => /^\d+$/.test(unit.vehicleId));
            if (!units.length) { health.lastError = 'Dispatch action had no readable selected vehicle IDs'; return; }
            const shared = control.classList.contains('alert_next_alliance') || /share/i.test(control.textContent || '');
            const dispatchMode = (typeof autoModeRunning !== 'undefined' && autoModeRunning ? 'auto' : 'manual') + (shared ? '-share' : '');
            const accepted = logger.emit('mission', {eventType:'dispatch', missionId,
                missionName:window.__NEXUS_COLLECTOR_GAME__?.missionName(missionId) || '',
                units, shared, dispatchMode, dispatchConfirmed:false, source:'nexus-dispatch-action'});
            if (accepted) health.accepted++;
            health.lastMissionId = missionId; health.lastAt = Date.now(); health.lastError = '';
        } catch {
            try { window.top.__NEXUS_DISPATCH_CAPTURE__.lastError = 'Dispatch action capture failed'; } catch {}
        }
    }


    function clickDispatchOnly() {
        const queueState =
            getNextMissionQueueState();
        const v3LowQueueBoundary =
            isV3LowQueuePauseSignal(
                queueState
            );
        const dispatchNextButton =
            !v3LowQueueBoundary && Array.from(
                document.querySelectorAll(
                    'a.alert_next'
                )
            ).find(button => {
                if (
                    !button ||
                    !isElementVisible(button)
                ) {
                    return false;
                }
                if (
                    button.id ===
                    'mission_next_mission_btn'
                ) {
                    return false;
                }
                const disabled =
                    button.hasAttribute(
                        'disabled'
                    ) ||
                    button.getAttribute(
                        'aria-disabled'
                    ) === 'true' ||
                    button.classList.contains(
                        'disabled'
                    );
                return !disabled;
            }) ||
            null;
        if (dispatchNextButton) {
            try {
                dispatchNextButton.scrollIntoView({
                    block: 'center',
                    inline: 'center'
                });
            } catch (error) {}
            try {
                captureNexusDispatchAction(dispatchNextButton);
            dispatchNextButton.click();
                return true;
            } catch (error) {
                return realClickForQueueRestart(
                    dispatchNextButton
                );
            }
        }
        const isDispatchOnlyBoundary =
            !!queueState?.exists &&
            (
                queueState.count === 0 ||
                v3LowQueueBoundary
            );
        if (!isDispatchOnlyBoundary) {
            return false;
        }
        const finalDispatchButton =
            Array.from(
                document.querySelectorAll(
                    'a#mission_alarm_btn'
                )
            ).find(button => {
                if (
                    !button ||
                    !isElementVisible(button)
                ) {
                    return false;
                }
                const disabled =
                    button.hasAttribute(
                        'disabled'
                    ) ||
                    button.getAttribute(
                        'aria-disabled'
                    ) === 'true' ||
                    button.classList.contains(
                        'disabled'
                    );
                if (disabled) {
                    return false;
                }
                const title = (
                    button.getAttribute(
                        'title'
                    ) ||
                    ''
                )
                    .replace(/\s+/g, ' ')
                    .trim()
                    .toLowerCase();
                const visibleText = (
                    button.textContent ||
                    button.innerText ||
                    ''
                )
                    .replace(/\s+/g, ' ')
                    .trim()
                    .toLowerCase();
                return (
                    title.startsWith(
                        'dispatch'
                    ) &&
                    !title.includes(
                        'next'
                    ) &&
                    visibleText.startsWith(
                        'dispatch'
                    )
                );
            }) ||
            null;
        if (!finalDispatchButton) {
            return false;
        }
        try {
            finalDispatchButton.scrollIntoView({
                block: 'center',
                inline: 'center'
            });
        } catch (error) {}
        try {
            captureNexusDispatchAction(finalDispatchButton);
            finalDispatchButton.click();
            return true;
        } catch (error) {
            return realClickForQueueRestart(
                finalDispatchButton
            );
        }
    }
