            if (hasVisibleQueueOpenModal(`resume-${reason}`)) {
                await wait(500);
                continue;
            }
            if (/\/missions\/\d+/i.test(window.location.pathname)) {
                await wait(500);
                continue;
            }
            await wait(500);
